from datetime import datetime
rows = [
    (1, '2026-11-02'), (2, '11/03/2026'), (3, '2026/11/04'),
    (4, 'Nov 5, 2026'), (5, '2026-11-06'), (6, '32/13/2026'),
    (7, 'next Friday'), (8, '2026/11/09'),
]
formats = ['%Y-%m-%d', '%m/%d/%Y', '%Y/%m/%d', '%b %d, %Y']
for cid, raw in rows:
    parsed = None
    for f in formats:
        try:
            parsed = datetime.strptime(raw, f).strftime('%Y-%m-%d')
            break
        except ValueError:
            pass
    print(f'id {cid}: {raw!r} -> {parsed}' if parsed else f'id {cid}: {raw!r} -> UNPARSEABLE')

def parse_money(s):
    t = s.strip().replace('$', '').replace(',', '')
    negative = t.startswith('(') and t.endswith(')')
    t = t.strip('()')
    try:
        v = float(t)
    except ValueError:
        return None
    return -v if negative else v
rows = [(1, '$1,200.00'), (2, '85.50'), (3, '(45.00)'), (4, '$2,340.75'), (5, '12'), (6, 'N/A')]
for cid, raw in rows:
    v = parse_money(raw)
    print(f'id {cid}: {raw!r} -> {v}' if v is not None else f'id {cid}: {raw!r} -> UNPARSEABLE')
